actions.script:
def out = [idleMin: 0, hasPin: false, name: ""]
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
    if (orgId && orgId != '_NA_') {
        def m = ec.entity.find("moqui.security.UserPreference").condition("userId", orgId)
            .condition("preferenceKey", "POS_IDLE_LOCK_MIN").one()?.preferenceValue
        if (m) { try { out.idleMin = Math.max(0, Math.min(240, (m.toString().trim() as int))) } catch (Exception e) { out.idleMin = 0 } }
    }
    def uid = ec.user.userId
    if (uid) {
        out.hasPin = (ec.entity.find("moqui.security.UserPreference").condition("userId", uid)
            .condition("preferenceKey", "POS_UNLOCK_PIN_HASH").one()?.preferenceValue) ? true : false
        def _ua = ec.entity.find("moqui.security.UserAccount").condition("userId", uid).one()
        out.name = _ua?.userFullName ?: (ec.user.username ?: "")
    }
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
ec.web.sendJsonResponse(out)

import java.security.MessageDigest
int MAXFAILS = 5
def sess = ec.web.session
int fails = 0
try { def f = sess.getAttribute("posUnlockFails"); if (f != null) fails = f as int } catch (Exception e) {}
def cred = (credential ?: "").toString()
def out = [ok: false, locked: false, attemptsLeft: Math.max(0, MAXFAILS - fails), passwordOnly: false]
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def uid = ec.user.userId
    if (!uid) { out.expired = true; ec.web.sendJsonResponse(out); return }
    boolean ok = false
    def stored = ec.entity.find("moqui.security.UserPreference").condition("userId", uid)
        .condition("preferenceKey", "POS_UNLOCK_PIN_HASH").one()?.preferenceValue
    if ((mode ?: "") == "pin" && stored && cred ==~ /\d{4,6}/) {
        def parts = stored.toString().split(":", 2)
        if (parts.length == 2) {
            def calc = MessageDigest.getInstance("SHA-256").digest((parts[0] + ":" + cred).getBytes("UTF-8")).encodeHex().toString()
            ok = (calc == parts[1])
        }
    } else {
        // password fallback (also the path when no PIN is set) — verify via Shiro like the login does
        def ua = ec.entity.find("moqui.security.UserAccount").condition("userId", uid).one()
        out.passwordOnly = !stored
        if (ua?.currentPassword && cred) {
            def token = new org.apache.shiro.authc.UsernamePasswordToken((String) ua.username, (String) cred)
            def info = new org.apache.shiro.authc.SimpleAuthenticationInfo((String) ua.username, (String) ua.currentPassword,
                    new org.apache.shiro.lang.util.SimpleByteSource((String) (ua.passwordSalt ?: "")), "moquiRealm")
            ok = ec.ecfi.getCredentialsMatcher(ua.passwordHashType, "Y".equals(ua.passwordBase64)).doCredentialsMatch(token, info)
        }
    }
    if (ok) {
        sess.setAttribute("posUnlockFails", 0)
        out.ok = true
    } else {
        fails = fails + 1
        sess.setAttribute("posUnlockFails", fails)
        out.attemptsLeft = Math.max(0, MAXFAILS - fails)
        out.locked = (fails >= MAXFAILS)
    }
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
ec.web.sendJsonResponse(out)

import java.security.MessageDigest
import java.security.SecureRandom
def out = [ok: false, msg: ""]
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def uid = ec.user.userId
    if (!uid) { out.msg = "Please sign in again."; ec.web.sendJsonResponse(out); return }
    def existing = ec.entity.find("moqui.security.UserPreference").condition("userId", uid)
        .condition("preferenceKey", "POS_UNLOCK_PIN_HASH").one()
    if (clear == 'Y' || clear == 'true') {
        if (existing != null) existing.delete()
        out.ok = true; out.msg = "PIN removed. You'll unlock with your password."
    } else {
        def p = (pin ?: "").toString().trim()
        if (!(p ==~ /\d{4}/)) { out.msg = "Enter exactly 4 digits."; ec.web.sendJsonResponse(out); return }
        byte[] sb = new byte[16]; new SecureRandom().nextBytes(sb)
        def salt = sb.encodeHex().toString()
        def hash = MessageDigest.getInstance("SHA-256").digest((salt + ":" + p).getBytes("UTF-8")).encodeHex().toString()
        def val = salt + ":" + hash
        if (existing != null) { existing.preferenceValue = val; existing.update() }
        else { ec.entity.makeValue("moqui.security.UserPreference").set("userId", uid).set("preferenceKey", "POS_UNLOCK_PIN_HASH").set("preferenceValue", val).create() }
        out.ok = true; out.msg = "Unlock PIN saved."
    }
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
ec.web.sendJsonResponse(out)

def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
if (!orgId || orgId == '_NA_') { ec.message.addError("No shop is selected for this session."); return }
int mins = 0
try { mins = (context.idleMin ?: '0').toString().trim() as int } catch (Exception e) { mins = 0 }
if (mins < 0) mins = 0
if (mins > 240) mins = 240
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def ex = ec.entity.find("moqui.security.UserPreference").condition("userId", orgId).condition("preferenceKey", "POS_IDLE_LOCK_MIN").one()
    if (ex != null) { ex.preferenceValue = mins.toString(); ex.update() }
    else { ec.entity.makeValue("moqui.security.UserPreference").set("userId", orgId).set("preferenceKey", "POS_IDLE_LOCK_MIN").set("preferenceValue", mins.toString()).create() }
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
ec.message.addMessage(mins > 0 ? ("Auto-lock set to " + mins + " minute" + (mins == 1 ? "" : "s") + ". Reopen the billing screen for it to take effect.") : "Auto-lock turned off.")

def orgId = ec.user.getPreference('ACTIVE_ORGANIZATION')
hasOrg = (orgId && orgId != '_NA_')
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def rd = { u, k -> ec.entity.find("moqui.security.UserPreference").condition("userId", u).condition("preferenceKey", k).one()?.preferenceValue }
    def m = hasOrg ? rd(orgId, 'POS_IDLE_LOCK_MIN') : null
    curIdleMin = (m != null && m.toString().trim() != '') ? m.toString().trim() : '0'
    idleDisplay = (curIdleMin == '0' || curIdleMin == '') ? 'Off' : ('Locks after ' + curIdleMin + ' min idle')
    pinDisplay = (ec.user.userId && rd(ec.user.userId, 'POS_UNLOCK_PIN_HASH')) ? 'Set' : 'Not set (unlock with your password)'
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
